namespace sv_808a18ba46d0410d9ad9daebb0d02c26.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Interactive Server mode, "scoped" = per-circuit = per-user tab.
/// The circuit persists across enhanced navigations, so theme state survives page changes.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        var changed = Theme != theme || AccentColor != accentColor;
        Theme = theme;
        AccentColor = accentColor;
        if (changed) OnChanged?.Invoke();
    }
}

@*
    This interactive component lives in the static layout.
    Because it has @rendermode InteractiveServer, it joins the circuit
    and shares the same scoped ThemeService as every interactive page.
    It uses JS interop to apply CSS classes/custom properties to <body>,
    making theme changes visible even in static-rendered markup.
*@
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator badge bg-secondary" title="Current theme">
    @GetThemeIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += OnThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDOM();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDOM();
        });
    }

    private async Task ApplyThemeToDOM()
    {
        var themeName = ThemeService.Theme.ToString().ToLowerInvariant();
        var accent = ThemeService.AccentColor;
        await JS.InvokeVoidAsync("applyTheme", themeName, accent);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "❓"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= OnThemeChanged;
    }
}

@*
    Reusable interactive toggle — drop this on any page or in the layout.
    Cycles through Light → Dark → System.
*@
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Toggle theme">
    @GetThemeIcon() Toggle Theme
</button>

@code {
    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _ => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "❓"
    };
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@ThemeService.Theme"
                    @onchange="OnThemeSelected">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@ThemeService.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@ThemeService.AccentColor</span>
            </div>
        </div>

        <p class="text-muted mt-3 mb-0">
            Changes apply immediately across the entire app.
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += OnServiceChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.SetTheme(mode);
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrEmpty(color))
        {
            ThemeService.SetAccentColor(color);
        }
    }

    private void OnServiceChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= OnServiceChanged;
    }
}

// Applies theme to the DOM so both static and interactive content respond.
window.applyTheme = function (theme, accentColor) {
    document.body.setAttribute("data-theme", theme);
    document.documentElement.style.setProperty("--accent-color", accentColor);
};

